//! Copyright (C) MOXA Inc. All rights reserved.
//!
//! This software is distributed under the terms of the
//! MOXA License.  See the file LICENSE for details.
//!
//! ===
//!
//! generate_iss_snmp_merge_table in 3rdparty_net_snmp

use std::env;
use std::fs::{remove_file, File, OpenOptions};
use std::io::{BufRead, BufReader, Write};
use std::path::Path;
use std::process::exit;
use std::process::Command;
use std::process::Stdio;

const MOXA_MIB_TABLE_PATH: &str = "/moxa/run/auto_mibs/";

#[derive(Debug)]
#[allow(dead_code)] // for name in struct TableOid
struct TableOid {
    name: String,
    iss_oid: String,
    mod_oid: String,
    dev_index_offset: u8,
    trunk_port_support: bool,
}

#[derive(Debug)]
struct TableFile {
    table_uri: String,
    table_tmp_file: String,
}

fn generate_snmp_merge_table(
    file_objs: &Vec<TableFile>,
    oid_objs: &Vec<TableOid>,
    oput_data_file: &str,
    oput_uptime: &str,
    max_port_num: u32,
) -> bool {
    println!("{:#?}", file_objs);
    println!("{:#?}", oid_objs);
    println!("--------/sbin/ies_uri_handle_client--------");

    let mut merge_file = String::new();
    for j in file_objs {
        let process_file = format!("{}{}", MOXA_MIB_TABLE_PATH, j.table_tmp_file);
        merge_file = format!("{}{} ", merge_file, process_file);
        if Path::new(&process_file).exists() {
            remove_file(&process_file).unwrap();
        }

        let ret_val = Command::new("/sbin/ies_uri_handle_client")
            .arg("--type")
            .arg("read")
            .arg("--uri")
            .arg(&j.table_uri)
            .arg("--file")
            .arg(&process_file)
            .output()
            .unwrap();
        if !ret_val.status.success() {
            return false;
        }
    }

    let iput_data_file = format!("{}merge_done", MOXA_MIB_TABLE_PATH);
    if Path::new(&iput_data_file).exists() {
        remove_file(&iput_data_file).unwrap();
    }

    let iput_file = File::create(&iput_data_file).unwrap();
    let stdio = Stdio::from(iput_file);
    let merge_files: Vec<&str> = merge_file.split(' ').filter(|s| &"" != s).collect();

    let ret_val = Command::new("/usr/bin/cat")
        .args(merge_files)
        .stdout(stdio)
        .output()
        .unwrap();
    if !ret_val.status.success() {
        return false;
    }

    let ret_val = Command::new("/bin/rm")
        .args(["-rf", &merge_file])
        .output()
        .unwrap();
    if !ret_val.status.success() {
        return false;
    }

    let mut oput_fp = OpenOptions::new()
        .read(true)
        .create(true)
        .append(true)
        .open(oput_data_file)
        .expect("Unable to open");

    writeln!(oput_fp, "#uptime={}", oput_uptime).unwrap();

    for i in oid_objs {
        let iput_fp = File::open(&iput_data_file).expect("Unable to open file");
        let reader = BufReader::new(iput_fp);
        for line in reader.lines() {
            if line.is_err() {
                continue;
            }
            let find_str = format!("{}.", i.iss_oid);

            let line = line.unwrap();
            if !line.contains(&find_str) {
                continue;
            }
            let result = line.get(find_str.len()..line.len()).unwrap();
            //			let result = &line[find_str.len()..line.len()];

            let replace_str = if i.dev_index_offset == 0 {
                let result_str = result.split('=').collect::<Vec<&str>>();
                let dev_index: u32 = result_str[0].parse().unwrap();
                if !i.trunk_port_support && dev_index > max_port_num {
                    continue;
                }

                line.replace(
                    &format!("{}.{}", i.iss_oid, dev_index),
                    &format!("{}.{}", i.mod_oid, dev_index),
                )
            } else if i.dev_index_offset == 1 {
                let result_str = result.split('.').collect::<Vec<&str>>();
                let dev_index: u32 = result_str[0].parse().unwrap();
                if !i.trunk_port_support && dev_index > max_port_num {
                    continue;
                }

                line.replace(
                    &format!("{}.{}.1", i.iss_oid, dev_index),
                    &format!("{}.{}", i.mod_oid, dev_index),
                )
            } else {
                return false;
            };

            writeln!(oput_fp, "{replace_str}").unwrap();
        }
    }

    remove_file(&iput_data_file).unwrap();
    true
}

fn generate_snmp_merge_mxlldp_port_table(
    oput_file: &str,
    oput_uptime: &str,
    max_port_num: u32,
) -> bool {
    let oid_objs = vec![
        TableOid {
            name: "mxlldp/portTable/portIdSubtype".to_owned(),
            iss_oid: "1.3.6.1.4.1.2076.158.2.3.1.1".to_owned(),
            mod_oid: "1.3.6.1.4.1.8691.603.5.1.1.4.1.1".to_owned(),
            dev_index_offset: 0,
            trunk_port_support: false,
        },
        TableOid {
            name: "mxlldp/portTable/portId".to_owned(),
            iss_oid: "1.3.6.1.4.1.2076.158.2.3.1.2".to_owned(),
            mod_oid: "1.3.6.1.4.1.8691.603.5.1.1.4.1.2".to_owned(),
            dev_index_offset: 0,
            trunk_port_support: false,
        },
        TableOid {
            name: "mxlldp/portTable/vlanNameTxEnable".to_owned(),
            iss_oid: "1.0.8802.1.1.2.1.5.32962.1.1.2.1.1".to_owned(),
            mod_oid: "1.3.6.1.4.1.8691.603.5.1.1.4.1.3".to_owned(),
            dev_index_offset: 1,
            trunk_port_support: false,
        },
    ];

    let file_objs = vec![
        TableFile {
            table_uri: "mxlldp/portTable/".to_owned(),
            table_tmp_file: "mxlldp_portTable.merge".to_owned(),
        },
        TableFile {
            table_uri: "stdot1lldp/vlanNameTable/".to_owned(),
            table_tmp_file: "stdot1lldp_vlanNameTable_portTable.merge".to_owned(),
        },
    ];

    generate_snmp_merge_table(&file_objs, &oid_objs, oput_file, oput_uptime, max_port_num)
}

fn generate_snmp_merge_mxvlan_vlanconfigport_table(
    oput_file: &str,
    oput_uptime: &str,
    max_port_num: u32,
) -> bool {
    /*
    #ifdef BCMX
        ''' VLAN Filtering Utility Criteria is not supported in BCMX '''
        oidObjs = [

            table_oid('fsvlandb/dot1qFutureVlanPortTable/dot1qFutureVlanPortType',
                      '1.3.6.1.4.1.2076.65.1.10.1.2',
                      '1.3.6.1.4.1.8691.603.2.3.1.4.1.2',
                      0, True),

            table_oid('stdvladb/dot1qPortVlanTable/dot1qPortAcceptableFrameTypes',
                      '1.3.6.1.2.1.17.7.1.4.5.1.2',
                      '1.3.6.1.4.1.8691.603.2.3.1.4.1.4',
                      0, True )
        ]
    #else
    */
    let oid_objs = vec![
        TableOid {
            name: "fsvlandb/dot1qFutureVlanPortTable/dot1qFutureVlanPortType".to_owned(),
            iss_oid: "1.3.6.1.4.1.2076.65.1.10.1.2".to_owned(),
            mod_oid: "1.3.6.1.4.1.8691.603.2.3.1.4.1.2".to_owned(),
            dev_index_offset: 0,
            trunk_port_support: true,
        },
        TableOid {
            name: "fsvlandb/dot1qFutureVlanPortTable/dot1qFutureVlanFilteringUtilityCriteria"
                .to_owned(),
            iss_oid: "1.3.6.1.4.1.2076.65.1.10.1.5".to_owned(),
            mod_oid: "1.3.6.1.4.1.8691.603.2.3.1.4.1.3".to_owned(),
            dev_index_offset: 0,
            trunk_port_support: true,
        },
        TableOid {
            name: "fsvlandb/dot1qFutureVlanPortTable/dot1qFutureVlanPortType".to_owned(),
            iss_oid: "1.3.6.1.2.1.17.7.1.4.5.1.2".to_owned(),
            mod_oid: "1.3.6.1.4.1.8691.603.2.3.1.4.1.4".to_owned(),
            dev_index_offset: 0,
            trunk_port_support: true,
        },
    ];
    /*
    #endif
    */

    let file_objs = vec![
        TableFile {
            table_uri: "fsvlandb/dot1qFutureVlanPortTable/".to_owned(),
            table_tmp_file: "fsvlandb_dot1qFutureVlanPortTable.merge".to_owned(),
        },
        TableFile {
            table_uri: "stdvladb/dot1qPortVlanTable/".to_owned(),
            table_tmp_file: "stdvladb_dot1qPortVlanTable.merge".to_owned(),
        },
    ];

    generate_snmp_merge_table(&file_objs, &oid_objs, oput_file, oput_uptime, max_port_num)
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 5 {
        exit(-1);
    }

    let iput_uri = &args[1];
    let oput_file = &args[2];
    let oput_uptime = &args[3];
    let max_port_num = args[4].parse::<u32>().unwrap();

    if Path::new(oput_file).exists() {
        remove_file(oput_file).unwrap();
    }

    let mut ret = false;
    if iput_uri == "mxlldp_portTable" {
        ret = generate_snmp_merge_mxlldp_port_table(oput_file, oput_uptime, max_port_num);
    } else if iput_uri == "mxvlan_vlanConfigPortTable" {
        ret = generate_snmp_merge_mxvlan_vlanconfigport_table(oput_file, oput_uptime, max_port_num);
    }

    match ret {
        true => exit(0),
        false => exit(-1),
    }
}

