fn generate_uri_table(
    max_port_num: u32,
    iput_uri: &str,
    iput_json: &serde_json::Value,
    oput_file: &mut File,
    oput_uptime: &str,
) -> bool {
    match iput_uri {
        "portMirror/portMirrorTable/" => {
            generate_portmirror_port_mirror_table(max_port_num, iput_json, oput_file, oput_uptime);
            true
        }
        "syslogServer/syslogFwdTable/" => {
            generate_syslog_server_syslog_fwd_table(iput_json, oput_file, oput_uptime);
            true
        }
        "trustedAccess/trustedIp/" => {
            generate_sys_trust_access_trust_ip_table(iput_json, oput_file, oput_uptime);
            true
