        "ipInterface/l3VlanIfTable/" => {
            generate_mx_ipif_l3_vlan_if_table(iput_json, oput_file, oput_uptime);
            true
        }
        "dhcpServer/dhcpTable/" => {
            generate_mx_dhcp_srv_dhcp_table(iput_json, oput_file, oput_uptime);
            true
        }
        "dhcpServer/macBasedIpTable/" => {
            generate_mx_dhcp_srv_mac_based_ip_table(iput_json, oput_file, oput_uptime);
            true
        }
        "dhcpServer/portBasedIpTable/" => {
            generate_mx_dhcp_srv_port_based_ip_table(iput_json, oput_file, oput_uptime);
            true
        }
        "dhcpServer/leaseTable/" => {
            generate_mx_dhcp_srv_status_lease_table(iput_json, oput_file, oput_uptime);
            true
        }
        #[cfg(feature = "MOXA_DHCP_SERVER_OPTION_121")]
        "dhcpServer/classlessStaticRouteTable/" => {
            generate_mx_dhcp_srv_classless_static_route_table(iput_json, oput_file, oput_uptime);
            true
        }
        "config/turboringv2/ring/" => {
            generate_mx_tr2_config_port_table(max_port_num, iput_json, oput_file, oput_uptime);
            true
        }
        "stat/turboringv2/ring/" => {
            generate_mx_tr2_stat_port_table(iput_json, oput_file, oput_uptime);
            true
        }
        #[cfg(feature = "MOXA_DRC")]
        "stat/turboringv2/dynRingCoupTable/" => {
            generate_mx_tr2_stat_dynamic_ring_coupling_table(
                max_port_num,
                iput_json,
                oput_file,
                oput_uptime,
            );
            true
        }
        "portEvent/portOn/portsPbmp" => {
            generate_port_event_port_on_ports_pbmp(iput_json, oput_file, oput_uptime);
            true
        }
        "portEvent/portOff/portsPbmp" => {
            generate_port_event_port_off_ports_pbmp(iput_json, oput_file, oput_uptime);
            true
        }
        "rateLimitEvent/rateLimitedOn/portsPbmp" => {
            generate_rate_limit_event_rate_limited_on_ports_pbmp(iput_json, oput_file, oput_uptime);
            true
        }
        "rateLimitEvent/rateLimitedOff/portsPbmp" => {
            generate_rate_limit_event_rate_limited_off_ports_pbmp(
                iput_json,
                oput_file,
                oput_uptime,
            );
            true
        }
        "psecEvent/psecViolationPortDown/portsPbmp" => {
            generate_psec_event_psec_violation_port_down_ports_pbmp(
                iput_json,
                oput_file,
                oput_uptime,
            );
            true
        }
        "lpEvent/loopProtectPortOff/portsPbmp" => {
            generate_lp_event_loop_protect_port_down_ports_pbmp(
                iput_json,
                oput_file,
                oput_uptime,
            );
            true
        }
        "chainProtectEvent/chainProtectionOn/portsPbmp" => {
            generate_turbo_chain_event_chain_protection_on_ports_pbmp(
                iput_json, 
                oput_file, 
                oput_uptime
            );
            true
        }
        "chainProtectEvent/chainProtectionOff/portsPbmp" => {
            generate_turbo_chain_event_chain_protection_off_ports_pbmp(
                iput_json,
                oput_file,
                oput_uptime,
            );
            true
        }
        "ringProtectEvent/ringProtectionOn/portsPbmp" => {
            generate_turbo_ring_event_ring_protection_on_ports_pbmp(
                iput_json, 
                oput_file, 
                oput_uptime
            );
            true
