            true
        }
        _ => false,
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 6 {
        exit(-1);
    }

    let iput_uri = &args[1];
    let iput_json_file = &args[2];
    let oput_data_file = &args[3];
    let oput_uptime = &args[4];
    let max_port_num = args[5].parse::<u32>().unwrap();

    if !Path::new(iput_json_file).exists() {
        exit(-1);
    }

    let tmp_iput_json_file = fs::read_to_string(iput_json_file).unwrap();
    let iput_json: serde_json::Value = serde_json::from_str(&tmp_iput_json_file).unwrap();

    if Path::new(oput_data_file).exists() {
        remove_file(oput_data_file).unwrap();
    }

    // FIXME: Add file-open-try-cache
    let mut oput_file = OpenOptions::new()
        .read(true)
        .create(true)
        .append(true)
        .open(oput_data_file)
        .unwrap();

    let ret = generate_uri_table(
        max_port_num,
        iput_uri,
        &iput_json,
        &mut oput_file,
        oput_uptime,
    );

    // oput_file.close()
    if ret {
        exit(0);
    } else {
        exit(-1);
    }
}

