fn generate_syslog_server_syslog_fwd_table(
    iput_json: &serde_json::Value,
    oput_file: &mut File,
    oput_uptime: &str,
) {
    // 'syslogServer/syslogFwdTable/'
    let uri_oid_str = "1.3.6.1.4.1.8691.602.8.2.1.2.1"; // From MIB
    let uri_table_range = iput_json.as_array().unwrap().len();
    let mut oid_index = 0;

    // Uptime
    writeln!(oput_file, "#uptime={}", oput_uptime).unwrap();

    // index
    oid_index += 1;
    for i in 0..uri_table_range {
        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
            uri_oid_str,
            oid_index,
            i + 1,
            i + 1,
        )
        .unwrap();
    }

    // syslogConfigServerEnable
    oid_index += 1;
    for i in 0..uri_table_range {
        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
            uri_oid_str,
            oid_index,
            i + 1,
            gen_value_turth_value(&iput_json[i]["enable"])
        )
        .unwrap();
    }

    // syslogServerAddress
    oid_index += 1;
    for i in 0..uri_table_range {
        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
            uri_oid_str,
            oid_index,
            i + 1,
            iput_json[i]["serverAddress"], // Rust: String
        )
        .unwrap();
    }

    // syslogServerPort
    oid_index += 1;
    for i in 0..uri_table_range {
        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
            uri_oid_str,
            oid_index,
            i + 1,
            iput_json[i]["serverPort"], // Rust: integer
        )
        .unwrap();
    }
}

