    iput_json: &serde_json::Value,
    oput_file: &mut File,
    oput_uptime: &str,
) {
    let uri_oid_str = "1.3.6.1.4.1.8691.605.1.1.1.1.1"; // From MIB
    let uri_table_range = iput_json.as_array().unwrap().len();

    // Uptime
    writeln!(oput_file, "#uptime={}", oput_uptime).unwrap();

    // index
    for i in 0..uri_table_range {
        writeln!(oput_file, "{}.{}.{}='{}'", uri_oid_str, 1, i + 1, i + 1,).unwrap();
    }

    // ifName to vlanId
    for i in 0..uri_table_range {
        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
            uri_oid_str,
            2,
            i + 1,
            gen_value_row_status_field_number(&serde_json::json!(
                iput_json[i]["ifName"].as_str().unwrap()[4..]
            ))
        )
        .unwrap();
    }

    // adminStatus
    for i in 0..uri_table_range {
        let config_admin_status = iput_json[i]["adminStatusUpEnable"]
            .as_bool()
            .unwrap_or(false);

        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
