        .unwrap();
    }

    // mtu
    for i in 0..uri_table_range {
        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
            uri_oid_str,
            4,
            i + 1,
            gen_value_row_status_field_number(&iput_json[i]["mtu"])
