/*-------------------------------------------------------------------+
 * Function           : ies_mibs_handle_iss_remap_merge_table_fname_and_file_uri
 *
 * Description        :


+-------------------------------------------------------------------*/
ies_handle_t 
ies_mibs_handle_iss_remap_merge_table_fname_and_file_uri
(
    struct ies_auto_mibs_entry   *entry, 
    char                         *fname,
    char                         *iput_uri
)
{

    LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "%s@%d: uri '%s' uri_index'%s' name'%s'\n", __func__, __LINE__, entry->uri, entry->uri_index, entry->name);

    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "mxlldp/portTable/") )
    {
        snprintf(iput_uri, IES_MAX_FILE, "%s", "mxlldp_portTable");
    } 
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "mxvlan/vlanConfigPortTable/") ) 
    {
        snprintf(iput_uri, IES_MAX_FILE, "%s", "mxvlan_vlanConfigPortTable");
    } 
    else 
    {
        return IES_ERR;
    }
    snprintf(fname, IES_MAX_FILE, "%s/%s_tbl", AUTO_MIB_PATH, iput_uri);

    return IES_NOERR;
}

#endif //_IES_MIBs_HANDLE_ISS_REMAP_MERGE_TABLE_C_

