file.content:
   Description     : opt process for uri handle type
   Input(s)        :
    @argc -- argc
    @argv -- argv
    @argv_index -- index of current argv
   Returns         : argv

   Note            :
+-------------------------------------------------------------------*/
ies_handle_t opts_type(char *input_buf, char *output_buf)
{
    struct opt_client *opt_client;
    if ( NULL == output_buf ) {
        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
        return IES_ERR;
    }
    opt_client = (struct opt_client *) output_buf;

    if ( 0 == strncmp( input_buf, "read", strlen("read") ) ) {
        opt_client->type = IES_URI_HANDLE_TYPE_READ;
    } else if ( 0 == strncmp( input_buf, "update", strlen("update") ) ) {
        opt_client->type = IES_URI_HANDLE_TYPE_UPDATE;
    } else if ( 0 == strncmp( input_buf, "read_oid_scalar", strlen("read_oid_scalar") ) ) {
        opt_client->type = IES_URI_HANDLE_TYPE_OID_READ_SCALAR;
    } else if ( 0 == strncmp( input_buf, "read_oid_table",  strlen("read_oid_table") ) ) {
        opt_client->type = IES_URI_HANDLE_TYPE_OID_READ_TABLE;
    } else if ( 0 == strncmp( input_buf, "update_oid",      strlen("update_oid") ) ) {
        opt_client->type = IES_URI_HANDLE_TYPE_OID_UPDATE;
    } else {
        return IES_ERR;
    }
    return IES_NOERR;
}


/*-------------------------------------------------------------------+
   Function Name   : opts_file
   Description     : opt process for uri handle file
   Input(s)        :
    @input_buf --  input buffer
    @output_buf   -- output buffer
   Returns         : IES_ERR / IES_NOERR

   Note            :
+-------------------------------------------------------------------*/
ies_handle_t opts_file(char *input_buf, char *output_buf)
{
    struct opt_client *opt_client;
    if ( NULL == output_buf ) {
        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
        return IES_ERR;
    }
    opt_client = (struct opt_client *) output_buf;
    snprintf((char *)opt_client->fname, IES_MAX_FILE, "%s", input_buf);
    return IES_NOERR;    
}



