import os,re
names=['stdlldOID','stdot3OID','stdcipOID','fslldmOID','slldv2OID','stdlldpmOID','sd3lv2OID','sd1lv2OID','stdpnoOID','stdot1OID','fslldpOID']
for root,dirs,files in os.walk('.'):
    for f in files:
        if not f.endswith(('.c','.h')): continue
        p=os.path.join(root,f); 
        try: s=open(p,errors='replace').read().split('\n')
        except: continue
        for i,l in enumerate(s):
            for n in names:
                if re.search(r'\b%s\b'%n,l) and ('{' in l or '=' in l) and 'SNMPRegister' not in l:
                    ctx=' '.join(x.strip() for x in s[i:i+4])
                    print('%-12s %s:%d  %s'%(n,p,i+1,ctx[:150]))
EOF

