import os,re
# 1) collect OID arrays
arrays={}
oidtypes=[]
for root,dirs,files in os.walk('.'):
    dirs[:]=[d for d in dirs if d not in ('.git',)]
    for f in files:
        if not f.endswith(('.c','.h')): continue
        p=os.path.join(root,f)
        try: s=open(p,errors='replace').read()
        except: continue
        for m in re.finditer(r'UINT4\s+(\w+)\s*\[\s*\]\s*=\s*\{([0-9,\s]+)\}',s):
            arrays[m.group(1)]=[x.strip() for x in m.group(2).split(',') if x.strip()]
        for m in re.finditer(r'tSNMP_OID_TYPE\s+(\w+)\s*=\s*\{\s*(\d+)\s*,\s*(\w+)\s*\}',s):
            oidtypes.append((p,m.group(1),int(m.group(2)),m.group(3)))
# 2) registered names
reg=set()
for root,dirs,files in os.walk('.'):
    for f in files:
        if not f.endswith(('.c','.h')): continue
        p=os.path.join(root,f)
        try: s=open(p,errors='replace').read()
        except: continue
        for m in re.finditer(r'SNMPRegisterMibWithLock\s*\(\s*&(\w+)',s):
            reg.add(m.group(1))
        for m in re.finditer(r'SNMPRegisterMib\s*\(\s*&(\w+)',s):
            reg.add(m.group(1))
print("registered OID vars:",len(reg))
